SELECT DISTINCTROW Имена_станций.NAME AS NAME1, w.YEAR, w.NUST, w.E, w.EOTP, w.EURT, w.EUST, w.Q, w.TURT, w.TUST, w.B, w.GAZ, w.MAZUT, w.TORF, w.SLAN, w.PROCH, w.UGOL, w.DON, w.PODM, w.PECH, w.ARKT, w.KUZN, w.URAL, w.BASHK, w.KAZAH, w.KAN, w.IRKUT, w.HAK, w.TUV, w.BUR, w.CHIT, w.YAKUT, w.AMUR, w.URG, w.PRIM, w.PRIM, w.MAG, w.SAH, w.QOTR, w.SNK, w.EWTP, w.NT, w.OBOR, w.VED, w.OBL, w.DEP, w.OES, w.ER, w.NUMB1120, Имена_станций.ordnumb AS numb1, Имена_областей.NAME AS oblname, Имена_станций.MAIN, Имена_ОЭС.name AS oesname, d.nazar, d.ibor, d.berez, d.per, d.gusin, d.tugn, d.azey, d.cher, d.vork, d.intin, d.sver, d.chel, d.kizel, d.kuzngd, d.kuznt, d.kuznss, d.kuznun
FROM ((([Рабочий(станции)] AS w INNER JOIN Имена_областей ON w.OBL = Имена_областей.OBL) INNER JOIN Имена_станций ON w.NUMB1120 = Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON w.OES = Имена_ОЭС.oes) LEFT JOIN [Рабочий(доп_угли)] AS d ON (w.YEAR = d.YEAR) AND (w.NUMB1120 = d.NUMB1120)
WHERE (((w.YEAR)>0) AND ((z([nust])+z([q]))>0));
